function readStoredJSON(key,fallback) { try { const value=localStorage.getItem(key); return value?JSON.parse(value):fallback; } catch(error) { return fallback; } }
function compactOwnerSpace(space) { const compact={...space}; const fallback=photos.emptyGallery; if(String(compact.image||'').startsWith('data:')) compact.image=fallback; if(String(compact.mainImage||'').startsWith('data:')) compact.mainImage=compact.image||fallback; compact.gallery=Array.isArray(compact.gallery)?compact.gallery.filter(image=>!String(image||'').startsWith('data:')).slice(0,6):[]; return compact; }
function saveOwnerData() { try { localStorage.setItem(OWNER_PROFILES_KEY,JSON.stringify(ownerProfiles)); localStorage.setItem(OWNER_SPACES_KEY,JSON.stringify(spaces.filter(space=>space.ownerProfileId).map(compactOwnerSpace))); } catch(error) { try { localStorage.setItem(OWNER_SPACES_KEY,JSON.stringify(spaces.filter(space=>space.ownerProfileId).map(space=>compactOwnerSpace({...space,gallery:[]})))); } catch(retryError) { console.warn('No se pudo guardar la información del propietario',retryError); } } }
