function saveUsers() { try { localStorage.setItem(USERS_KEY,JSON.stringify(users)); if(sessionUser) localStorage.setItem(SESSION_KEY,JSON.stringify(sessionUser)); else localStorage.removeItem(SESSION_KEY); localStorage.setItem(RESERVATIONS_KEY,JSON.stringify(reservations)); } catch(error) { console.warn('No se pudo guardar la cuenta local',error); } }
function initialsFor(name) { return String(name||'Usuario').split(/\s+/).filter(Boolean).slice(0,2).map(word=>word[0]).join('').toUpperCase(); }
function registerLocalUser({name,email,phone,password,role,accountType='Propietario'}) { const normalized=String(email||'').trim().toLowerCase(); const existing=users.find(user=>user.email===normalized); if(existing) { sessionUser=existing; saveUsers(); return existing; } const user={id:`USER-${Date.now()}`,name:String(name).trim(),email:normalized,phone:String(phone||'').trim(),password:String(password||''),role,accountType,createdAt:new Date().toISOString()}; users.push(user); sessionUser=user; saveUsers(); return user; }
function reuseOwnerProfileOnPublish() { const owner=sessionUser?.role==='owner'?sessionUser:null; const panel=document.querySelector('.owner-details'); if(!panel||!owner) return; const name=panel.querySelector('#owner-name'); const email=panel.querySelector('#owner-email'); const phone=panel.querySelector('#owner-phone'); const password=panel.querySelector('#owner-password'); const consent=panel.querySelector('#owner-consent'); if(name) name.value=owner.name||''; if(email) email.value=owner.email||''; if(phone) phone.value=owner.phone||''; if(password) password.value=''; if(consent) consent.checked=true; panel.classList.add('owner-details-reused'); panel.querySelector('.panel-help')?.replaceChildren(document.createTextNode('Usaremos tu perfil de propietario activo para este nuevo espacio.')); panel.querySelectorAll('input,select').forEach(field=>{ if(field.id!=='owner-consent') field.disabled=true; }); panel.style.display='none'; }
async function upsertSupabaseProfile(authUser,details={}) { if(!supabaseClient||!authUser) return null; const profile={id:authUser.id,role:details.role||authUser.user_metadata?.role||'entrepreneur',full_name:details.name||authUser.user_metadata?.full_name||'',email:authUser.email,phone:details.phone||authUser.user_metadata?.phone||'',account_type:details.accountType||authUser.user_metadata?.account_type||'Emprendedor'}; const {data,error}=await supabaseClient.from('profiles').upsert(profile).select().single(); if(error) throw error; sessionUser={id:authUser.id,name:data.full_name,email:data.email,phone:data.phone,role:data.role,accountType:data.account_type,createdAt:data.created_at,authUser:true}; return sessionUser; }
async function registerUserAccount(details) { if(!supabaseClient) return registerLocalUser(details); const {data,error}=await supabaseClient.auth.signUp({email:details.email,password:details.password,options:{data:{role:details.role,full_name:details.name,phone:details.phone||'',account_type:details.accountType||''}}}); if(error) throw error; if(!data.user) throw new Error('Supabase no devolvió el usuario'); if(!data.session) return {pendingConfirmation:true,id:data.user.id,name:details.name,email:details.email,phone:details.phone,role:details.role,accountType:details.accountType}; return upsertSupabaseProfile(data.user,details); }
async function loginUserFromProfile() { const email=document.querySelector('#login-email')?.value.trim(); const password=document.querySelector('#login-password')?.value; if(!email||!password) { toast('Escribe correo y contraseña'); return; } try { if(!supabaseClient) { const user=users.find(item=>item.email===email.toLowerCase()&&item.password===password); if(!user) throw new Error('Correo o contraseña incorrectos'); sessionUser=user; saveUsers(); render(); return; } const {data,error}=await supabaseClient.auth.signInWithPassword({email,password}); if(error) throw error; await upsertSupabaseProfile(data.user); toast('Sesión iniciada'); render(); } catch(error) { toast(error.message||'No se pudo iniciar sesión'); } }
async function logoutUser() { if(supabaseClient) await supabaseClient.auth.signOut(); sessionUser=null; saveUsers(); active='discover'; render(); toast('Sesión cerrada'); }
async function registerUserFromProfile() { const name=document.querySelector('#account-name')?.value.trim(); const email=document.querySelector('#account-email')?.value.trim(); const phone=document.querySelector('#account-phone')?.value.trim(); const password=document.querySelector('#account-password')?.value; const role=document.querySelector('#account-role')?.value||'entrepreneur'; if(!name||!email||!password) { toast('Completa nombre, correo y contraseña'); return; } if(password.length<6) { toast('La contraseña debe tener mínimo 6 caracteres'); return; } try { const user=await registerUserAccount({name,email,phone,password,role,accountType:role==='owner'?'Propietario':'Emprendedor'}); if(user.pendingConfirmation) { toast('Revisa tu correo para confirmar la cuenta y luego inicia sesión'); return; } if(role==='owner'&&!ownerProfiles.some(profile=>profile.userId===user.id)) { ownerProfiles.push({id:`OWNER-${Date.now()}`,userId:user.id,name:user.name,email:user.email,phone:user.phone,accountType:'Propietario',createdAt:user.createdAt}); saveOwnerData(); } toast(`Cuenta de ${role==='owner'?'propietario':'emprendedor'} creada`); render(); } catch(error) { toast(error.message||'No se pudo crear la cuenta'); } }
async function registerEntrepreneurFromReservation() { const name=document.querySelector('#guest-name')?.value.trim(); const email=document.querySelector('#guest-email')?.value.trim(); const phone=document.querySelector('#guest-phone')?.value.trim(); const password=document.querySelector('#guest-password')?.value; const consent=document.querySelector('#guest-consent')?.checked; if(!name||!email||!password||!consent) { toast('Completa tus datos, contraseña y acepta los términos'); return; } if(password.length<6) { toast('La contraseña debe tener mínimo 6 caracteres'); return; } try { const user=await registerUserAccount({name,email,phone,password,role:'entrepreneur',accountType:'Emprendedor'}); if(user.pendingConfirmation) { toast('Confirma tu correo y luego inicia sesión para continuar'); active='profile'; render(); return; } reservationState.guestName=user.name; reservationState.guestEmail=user.email; reservationState.userId=user.id; active='payment'; render(); } catch(error) { toast(error.message||'No se pudo crear la cuenta'); } }
async function loadSupabaseSession() { if(!supabaseClient) return; const {data}=await supabaseClient.auth.getSession(); if(data.session) { try { await upsertSupabaseProfile(data.session.user); await loadRemoteOwnerData(); await loadOwnerOffers(); await loadRetentionData(); subscribeToSharedSpaces(); if(active==='discover'||active==='profile'||active==='owner') render(); } catch(error) { console.warn('No se pudo cargar el perfil de Supabase',error); } } else { sessionUser=null; saveUsers(); if(active==='profile'||active==='owner') render(); } supabaseClient.auth.onAuthStateChange((_event,session)=>{ if(session) upsertSupabaseProfile(session.user).then(loadRemoteOwnerData).then(loadOwnerOffers).then(loadRetentionData).then(()=>{subscribeToSharedSpaces(); if(active==='profile'||active==='owner'||active==='discover') render();}).catch(console.warn); else { spacesRealtimeChannel?.unsubscribe(); sessionUser=null; saveUsers(); active=active==='owner'?'discover':active; if(active==='profile'||active==='discover') render(); } }); }
async function persistSpaceToSupabase(space) { if(!supabaseClient||!sessionUser?.authUser) return; const metadata={gallery:space.gallery||[],tags:space.tags||[],badge:space.badge||'Publicado',businessTypes:space.businessTypes||['Otros'],spaceType:space.spaceType||'',area:space.area||'',areaUnit:space.areaUnit||'m²',activities:space.activities||[],access:space.access||'',availabilityOptions:space.availabilityOptions||[],conditions:space.conditions||{},ownerName:space.ownerName||sessionUser.name||'',ownerEmail:space.ownerEmail||sessionUser.email||'',ownerPhone:space.ownerPhone||sessionUser.phone||'',ownerAccountType:space.ownerAccountType||sessionUser.accountType||'Propietario'}; const {error}=await supabaseClient.from('spaces').upsert({id:space.id,owner_id:sessionUser.id,name:space.name||space.title,location:space.location,description:space.description,price:space.price,unit:space.unit,furnishing:space.furnishing,image:space.image,latitude:space.latitude,longitude:space.longitude,status:'available',metadata}); if(error) throw error; }
async function uploadPropertyPhotos(spaceId,ownerId) { if(!supabaseClient||!propertyPhotoFiles.length) return []; const urls=[]; for(const file of propertyPhotoFiles.slice(0,6)) { const safeName=file.name.replace(/[^a-zA-Z0-9._-]/g,'-'); const path=`${ownerId}/${spaceId}/${crypto.randomUUID()}-${safeName}`; const {error}=await supabaseClient.storage.from('property-photos').upload(path,file,{upsert:false,contentType:file.type||'image/jpeg'}); if(error) throw error; const {data}=supabaseClient.storage.from('property-photos').getPublicUrl(path); if(data?.publicUrl) urls.push(data.publicUrl); } return urls; }
async function persistReservationToSupabase(record) { if(!supabaseClient||!sessionUser?.authUser) return; const space=reservationSpace(); const {error}=await supabaseClient.from('reservations').upsert({id:record.id,user_id:record.userId,owner_id:space.ownerId||null,space_id:record.spaceId,quantity:record.quantity,unit:record.unit,total:record.total,status:'requested',start_date:record.startDate||null,end_date:record.endDate||null}); if(error) throw error; }
function remoteSpaceToLocal(remote) { const metadata=remote.metadata||{}; const reservedUntil=remote.reserved_until||null; const isReserved=reservedUntil&&new Date(`${reservedUntil}T23:59:59`)>=new Date(); return {id:remote.id,title:remote.name,name:remote.name,location:remote.location,description:remote.description||'Espacio comercial publicado en Localmente.',price:Number(remote.price)||0,unit:remote.unit||'/día',prices:{day:Number(remote.price)||0},furnishing:remote.furnishing||'Sin amoblar',image:remote.image||photos.emptyGallery,mainImage:remote.image||photos.emptyGallery,gallery:metadata.gallery||[],latitude:Number(remote.latitude),longitude:Number(remote.longitude),availability:isReserved?'Reservado':'Disponible',reservedFrom:remote.reserved_from||null,reservedUntil,rating:null,distance:'Cerca de ti',tags:metadata.tags||['Publicado'],badge:isReserved?'Reservado':metadata.badge||'Publicado',businessTypes:metadata.businessTypes||['Otros'],ownerProfileId:`OWNER-${remote.owner_id}`,ownerId:remote.owner_id,ownerName:metadata.ownerName||'Propietario Localmente',ownerEmail:metadata.ownerEmail||'',ownerPhone:metadata.ownerPhone||'',ownerAccountType:metadata.ownerAccountType||'Propietario',spaceType:metadata.spaceType||'Local comercial',area:metadata.area||'',areaUnit:metadata.areaUnit||'m²',activities:metadata.activities||[],access:metadata.access||'',availabilityOptions:metadata.availabilityOptions||[],conditions:metadata.conditions||{},createdAt:remote.created_at}; }
async function loadRemoteOwnerData() { if(!supabaseClient||!sessionUser?.authUser) return; const {data,error}=await supabaseClient.from('spaces').select('*').order('created_at',{ascending:false}); if(error) throw error; (data||[]).forEach(remote=>{ const incoming=remoteSpaceToLocal(remote); const index=spaces.findIndex(space=>space.id===incoming.id); if(index===-1) spaces.push(incoming); else spaces[index]={...spaces[index],...incoming}; }); if(!ownerProfiles.some(profile=>profile.userId===sessionUser.id)) { ownerProfiles.push({id:`OWNER-${sessionUser.id}`,userId:sessionUser.id,name:sessionUser.name,email:sessionUser.email,phone:sessionUser.phone,accountType:sessionUser.accountType,createdAt:sessionUser.createdAt}); saveOwnerData(); } }
async function loadPublicSpaces() { if(!supabaseClient) return; try { const {data,error}=await supabaseClient.from('spaces').select('*').eq('status','available').order('created_at',{ascending:false}); if(error) throw error; (data||[]).forEach(remote=>{ const incoming=remoteSpaceToLocal(remote); const index=spaces.findIndex(space=>space.id===incoming.id); if(index===-1) spaces.push(incoming); else spaces[index]={...spaces[index],...incoming}; }); if(active==='discover'||active==='map') render(); } catch(error) { console.warn('No se pudieron cargar los espacios públicos de Supabase',error); } }
let spacesRealtimeChannel=null;
function subscribeToSharedSpaces() { if(!supabaseClient||!sessionUser?.authUser) return; spacesRealtimeChannel?.unsubscribe(); spacesRealtimeChannel=supabaseClient.channel('localmente-shared-spaces').on('postgres_changes',{event:'*',schema:'public',table:'spaces'},payload=>{ if(payload.eventType==='DELETE') { const index=spaces.findIndex(space=>space.id===payload.old.id); if(index>=0) spaces.splice(index,1); } else if(payload.new) { const incoming=remoteSpaceToLocal(payload.new); const index=spaces.findIndex(space=>space.id===incoming.id); if(index===-1) spaces.unshift(incoming); else spaces[index]={...spaces[index],...incoming}; } if(['discover','map','owner'].includes(active)) render(); if(payload.eventType==='INSERT'&&payload.new?.owner_id!==sessionUser.id) toast('Nuevo espacio publicado en Localmente'); }).subscribe(); }
function followedSpaceIds() { return readStoredJSON('localmente.followedSpaces.v1',[]); }
async function followSpace(spaceId) { if(!sessionUser?.authUser) { active='profile'; render(); toast('Inicia sesión para seguir este espacio'); return; } const ids=followedSpaceIds(); const following=ids.includes(spaceId); const next=following?ids.filter(id=>id!==spaceId):[...ids,spaceId]; localStorage.setItem('localmente.followedSpaces.v1',JSON.stringify(next)); try { if(following) await supabaseClient.from('space_follows').delete().eq('user_id',sessionUser.id).eq('space_id',spaceId); else await supabaseClient.from('space_follows').insert({user_id:sessionUser.id,space_id:spaceId}); toast(following?'Dejaste de seguir el espacio':'Te avisaremos cuando vuelva a estar disponible'); render(); } catch(error) { toast(error.message||'No se pudo actualizar el seguimiento'); } }
function openOfferModal(spaceId) { if(!sessionUser?.authUser) { active='profile'; render(); toast('Inicia sesión para enviar una oferta'); return; } const space=spaces.find(item=>item.id===spaceId); if(!space) return; document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)this.remove()"><div class="modal offer-modal"><button class="icon-btn modal-close" onclick="this.closest('.modal-backdrop').remove()"><span class="material-symbols-outlined">close</span></button><p class="eyebrow">Oferta para después de la reserva</p><h2>${escapeHTML(space.name||space.title)}</h2><p class="panel-help">El propietario decidirá si acepta tu propuesta cuando el espacio quede libre.</p><div class="form-field"><label>VALOR QUE OFRECES</label><input id="offer-amount" type="number" min="0" value="${Number(space.price)||0}"></div><div class="form-field"><label>FECHA DESDE LA QUE LO NECESITAS</label><input id="offer-start" type="date" min="${new Date().toISOString().slice(0,10)}"></div><div class="form-field"><label>MENSAJE AL PROPIETARIO</label><textarea id="offer-message" rows="4" placeholder="Cuéntale qué actividad realizarás y por cuánto tiempo."></textarea></div><button class="primary-btn full" onclick="submitSpaceOffer('${spaceId}')">Enviar oferta</button></div></div>`; }
async function submitSpaceOffer(spaceId) { const space=spaces.find(item=>item.id===spaceId); const amount=Number(document.querySelector('#offer-amount')?.value)||0; const proposedStart=document.querySelector('#offer-start')?.value||null; const message=document.querySelector('#offer-message')?.value.trim()||''; if(!amount||!proposedStart) { toast('Completa el valor y la fecha de tu oferta'); return; } try { const {error}=await supabaseClient.from('space_offers').insert({id:`OFR-${Date.now()}`,space_id:spaceId,user_id:sessionUser.id,owner_id:space.ownerId,amount,unit:space.unit||'/día',proposed_start:proposedStart,message}); if(error) throw error; document.querySelector('.modal-backdrop')?.remove(); toast('Oferta enviada al propietario'); } catch(error) { toast(error.message||'No se pudo enviar la oferta'); } }
function persistReservation() { const record={id:reservationState.id||`RES-${Date.now()}`,userId:reservationState.userId||sessionUser?.id||null,spaceId:reservationSpace().id,spaceName:reservationSpace().name||reservationSpace().title,quantity:Number(reservationState.quantity)||1,unit:reservationState.unit,total:reservationTotal().total,startDate:reservationState.start||null,endDate:reservationState.end||null,createdAt:new Date().toISOString(),status:'Solicitud enviada'}; if(!reservations.some(item=>item.id===record.id)) reservations.push(record); reservationState.id=record.id; saveUsers(); if(supabaseClient&&sessionUser?.authUser) persistReservationToSupabase(record).catch(error=>console.warn('No se pudo guardar la reserva en Supabase',error)); return record; }
const mapState={business:'all',furnishing:'all',availability:'all',price:'all'};
let active = new URLSearchParams(location.search).get('screen') || 'discover';
const searchState = { location:'Yopal, Colombia', nameQuery:'', type:'Cualquier categoría', dates:'Agregar fechas', budget:'Cualquier presupuesto', furnishing:'all' };
const locationState = { status:'idle', latitude:null, longitude:null, city:'', country:'', requested:false };
const app = document.querySelector('#app');
const toast = message => { const el = document.querySelector('#toast'); el.textContent = message; el.classList.add('show'); clearTimeout(window.toastTimer); window.toastTimer = setTimeout(()=>el.classList.remove('show'),2200); };
function distanceKm(aLat,aLon,bLat,bLon) { const toRad=value=>value*Math.PI/180; const dLat=toRad(bLat-aLat); const dLon=toRad(bLon-aLon); const a=Math.sin(dLat/2)**2+Math.cos(toRad(aLat))*Math.cos(toRad(bLat))*Math.sin(dLon/2)**2; return 6371*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a)); }
function nearestKnownCity(latitude,longitude) { return Object.entries(cityCenters).map(([city,[lat,lon]])=>({city,distance:distanceKm(latitude,longitude,lat,lon)})).sort((a,b)=>a.distance-b.distance)[0]; }
function userLocationLabel() { if (locationState.status==='ready') return `Espacios cerca de ${locationState.city}`; if (locationState.status==='loading') return 'Detectando tu ubicación…'; return 'Activa tu ubicación para ver espacios cercanos'; }
async function reverseGeocode(latitude,longitude) { const url=`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${latitude}&lon=${longitude}&zoom=10&addressdetails=1&accept-language=es`; const response=await fetch(url,{headers:{Accept:'application/json'}}); if(!response.ok) throw new Error('No se pudo identificar la ciudad'); const data=await response.json(); const address=data.address||{}; return {city:address.city||address.town||address.village||address.municipality||address.county,country:address.country||''}; }
function applyDetectedLocation(latitude,longitude,city,country,displayLabel='') { const label=city&&country?`${city}, ${country}`:nearestKnownCity(latitude,longitude)?.city||'Yopal, Colombia'; locationState.status='ready'; locationState.latitude=latitude; locationState.longitude=longitude; locationState.city=city||label.split(',')[0]; locationState.country=country||label.split(',')[1]?.trim()||'Colombia'; searchState.location=displayLabel||label; if(!cityCenters[label]) cityCenters[label]=[latitude,longitude]; toast(`Ubicación detectada: ${displayLabel||label}`); render(); }
async function searchForLocation(query) { const value=String(query||'').trim(); if(!value) return; locationState.status='loading'; searchState.location=value; toast('Buscando esa ubicación…'); try { const response=await fetch(`https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&addressdetails=1&accept-language=es&q=${encodeURIComponent(value)}`,{headers:{Accept:'application/json'}}); if(!response.ok) throw new Error('No se pudo buscar la ubicación'); const results=await response.json(); const result=results[0]; if(!result) throw new Error('Ubicación no encontrada'); const address=result.address||{}; const city=address.city||address.town||address.village||address.municipality||address.county; applyDetectedLocation(Number(result.lat),Number(result.lon),city,address.country,result.display_name||value); } catch(error) { locationState.status='manual'; render(); toast('No encontramos ese lugar. Prueba con ciudad, barrio o dirección.'); } }
let locationAutocompleteTimer=null;
function escapeHTML(value) { return String(value).replace(/[&<>"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[char])); }
function locationSuggestionMenu(input) { let menu=input.parentElement.querySelector('.location-suggestions'); if(!menu) { menu=document.createElement('div'); menu.className='location-suggestions'; input.parentElement.appendChild(menu); } return menu; }
async function loadLocationSuggestions(input) { const query=input.value.trim(); const menu=locationSuggestionMenu(input); if(query.length<3) { menu.classList.remove('show'); menu.innerHTML=''; return; } menu.innerHTML='<div class="location-suggestion pending">Buscando lugares…</div>'; menu.classList.add('show'); const requested=query; try { const response=await fetch(`https://nominatim.openstreetmap.org/search?format=jsonv2&limit=5&addressdetails=1&accept-language=es&q=${encodeURIComponent(query)}`,{headers:{Accept:'application/json'}}); const results=await response.json(); if(input.value.trim()!==requested) return; menu.innerHTML=results.length?results.map(result=>`<button type="button" class="location-suggestion" data-location-result="${encodeURIComponent(result.display_name)}"><span class="material-symbols-outlined">location_on</span><span>${escapeHTML(result.display_name)}</span></button>`).join(''):'<div class="location-suggestion pending">No encontramos coincidencias</div>'; menu.querySelectorAll('[data-location-result]').forEach(item=>item.onclick=()=>{ const value=decodeURIComponent(item.dataset.locationResult); input.value=value; menu.classList.remove('show'); searchForLocation(value); }); } catch(error) { menu.classList.remove('show'); } }
document.addEventListener('input',event=>{ if(event.target.id!=='location-search') return; clearTimeout(locationAutocompleteTimer); locationAutocompleteTimer=setTimeout(()=>loadLocationSuggestions(event.target),300); });
document.addEventListener('focusin',event=>{ if(event.target.id==='location-search'&&event.target.value.trim().length>=3) loadLocationSuggestions(event.target); });
document.addEventListener('click',event=>{ const card=event.target.closest('.view > .cards .card'); if(active==='discover'&&card&&!event.target.closest('.heart')) { const cards=[...document.querySelectorAll('.view > .cards .card')]; const item=recommendedSpaces()[cards.indexOf(card)]; if(item?.id) { selectedSpaceId=item.id; active='spaceDetail'; render(); } } });
function closeHotPopup() { sessionStorage.setItem('localmente-hot-popup-closed','true'); document.querySelector('.hot-popup-backdrop')?.remove(); }
function openHotProperty() { let hotSpace=spaces.find(space=>space.id==='HOT-YOPAL-0001'); if(!hotSpace) { hotSpace={id:'HOT-YOPAL-0001',title:'Local HOT Centro de Yopal',name:'Local HOT Centro de Yopal',location:'Centro de Yopal, Casanare',latitude:5.337,longitude:-72.395,mainImage:photos.facadeYopal,image:photos.facadeYopal,price:4500,unit:'/hora',prices:{hour:4500,day:32000,week:180000},tags:['Retail','Flexible'],furnishing:'Sin amoblar',availability:'Disponible',rating:4.9,reviewCount:24,distance:'En el centro',businessTypes:['Local comercial'],description:'Un local estratégico para poner en marcha tu próxima idea de negocio.'}; spaces.push(hotSpace); } selectedSpaceId=hotSpace.id; active='spaceDetail'; render(); }
function showHotPopup() { if(active!=='discover'||sessionStorage.getItem('localmente-hot-popup-closed')||document.querySelector('.hot-popup-backdrop')) return; const root=document.querySelector('#modal-root'); if(!root) return; root.innerHTML=`<div class="modal-backdrop hot-popup-backdrop"><div class="modal hot-popup"><button class="icon-btn modal-close" onclick="closeHotPopup()" aria-label="Cerrar"><span class="material-symbols-outlined">close</span></button><div class="hot-popup-image" style="background-image:url('${photos.emptyGallery}')"><span class="hot-label"><span class="material-symbols-outlined">local_fire_department</span> LOCAL HOT</span></div><div class="hot-popup-content"><p class="eyebrow">Una oportunidad cerca de ti</p><h2>Este local está esperando por tu emprendimiento</h2><p>Abre tu próxima idea en el centro de Yopal, Casanare, en un espacio listo para empezar.</p><div class="hot-price"><span>Desde</span><strong>$4.500</strong><small>por hora</small></div><button class="primary-btn full" onclick="closeHotPopup();openHotProperty()">Ver este local <span aria-hidden="true">→</span></button><small class="hot-popup-note">Cupos promocionales sujetos a disponibilidad.</small></div></div></div>`; }
async function requestUserLocation(force=false) { if(locationState.requested&&!force) return; locationState.requested=true; if(!navigator.geolocation){ locationState.status='unavailable'; return; } locationState.status='loading'; if(active==='discover') render(); navigator.geolocation.getCurrentPosition(async position=>{ const {latitude,longitude}=position.coords; try { const place=await reverseGeocode(latitude,longitude); applyDetectedLocation(latitude,longitude,place.city,place.country); } catch(error) { const fallback=nearestKnownCity(latitude,longitude); applyDetectedLocation(latitude,longitude,fallback?.city?.split(',')[0],fallback?.city?.split(',')[1]?.trim()); } },()=>{ locationState.status='denied'; if(active==='discover') render(); toast('Puedes activar la ubicación desde el navegador para recibir sugerencias cercanas'); },{enableHighAccuracy:true,timeout:10000,maximumAge:300000}); }
const navItems = [['discover','Inicio','home'],['map','Explorar mapa','map'],['potential','Espacios con potencial','add_business'],['favorites','Favoritos','favorite'],['inbox','Mensajes','chat_bubble'],['owner','Soy propietario','storefront'],['profile','Cuenta / usuarios','account_circle'],['verify','Verificar negocio','verified_user']];
function shell(content) { app.innerHTML = `<div class="app-shell"><aside class="sidebar"><div class="brand"><img src="${logo}" alt="Localmente"/></div><nav class="nav">${navItems.map(([id,label,icon])=>`<button class="${active===id?'active':''}" data-route="${id}"><span class="material-symbols-outlined">${icon}</span><span>${label}</span></button>`).join('')}</nav><div class="sidebar-bottom"><button class="profile-chip profile-chip-button" onclick="active='profile';render()"><div class="avatar">${escapeHTML(initialsFor(sessionUser?.name||'Usuario'))}</div><div><strong>${escapeHTML(sessionUser?.name||'Crear usuario')}</strong><small>${sessionUser?(sessionUser.role==='owner'?'Propietario':'Emprendedor'):'Iniciar sesión'}</small></div></button></div></aside><main class="main"><div class="topbar"><div><p class="eyebrow">Localmente</p><h2>${active==='owner'?'Panel del propietario':active==='profile'?'Cuenta y usuarios':active==='verify'?'Verificación del negocio':active==='potential'?'Espacios con potencial de local':active==='publish'?'Crear registro de espacio':'Encuentra tu próximo lugar'}</h2></div><div class="top-actions"><button class="icon-btn" title="Notificaciones" onclick="toast('No tienes alertas nuevas')"><span class="material-symbols-outlined">notifications</span></button><button class="icon-btn account-launcher" title="Cuenta / crear usuario" aria-label="Abrir cuenta y crear usuario" onclick="active='profile';render()"><span class="material-symbols-outlined">account_circle</span></button><button class="primary-btn" onclick="openReserve()">Publicar espacio</button></div></div>${content}</main></div><div id="modal-root"></div>`; document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{active=b.dataset.route; render()}); }
function card(item) { const amount=typeof item.price==='number'?`$${new Intl.NumberFormat('es-CO').format(item.price)}`:item.price; return `<article class="card"><div class="card-image" style="background-image:url('${item.image}')"><span class="badge ${item.orange?'orange':''}">${item.badge||'Disponible'}</span><button class="heart" onclick="toggleHeart(this)"><span class="material-symbols-outlined">favorite</span></button></div><div class="card-content"><h3>${item.title||item.name}</h3><div class="card-location"><span class="material-symbols-outlined">location_on</span>${item.location}</div><div class="card-meta"><div class="tags">${(item.tags||[]).map(t=>`<span class="tag">${t}</span>`).join('')}</div><div class="price">${amount}<small>${item.unit}</small></div></div></div></article>`; }
const generatedImagePool=[photos.facadeBogota,photos.facadeCali,photos.facadeBarranquilla,photos.facadeYopal,photos.loft,photos.studio,photos.cafe,photos.showroom,photos.garage];
function recommendedSpaces() { const city=normalizeCity(searchState.location); const candidates=ensureCitySpaces(city); candidates.forEach((space,index)=>{if(space.id?.startsWith('LOC-')&&!listings.some(item=>item.title===space.title)){const image=generatedImagePool[index%generatedImagePool.length]; space.image=image; space.mainImage=image;}}); if(!locationState.latitude||!locationState.longitude) return candidates.slice(0,9); return candidates.map(space=>({...space,nearbyDistance:distanceKm(locationState.latitude,locationState.longitude,space.latitude,space.longitude)})).sort((a,b)=>a.nearbyDistance-b.nearbyDistance).slice(0,9); }
function discover() { const resultLabel=searchState.furnishing==='unfurnished'?'Espacios vacíos y sin amoblar':searchState.furnishing==='furnished'?'Espacios amoblados':locationState.status==='ready'?'Espacios recomendados cerca de ti':'Populares cerca de ti'; return `<section class="view"><div class="hero"><div><p class="eyebrow" style="color:#bfffe7">Tu espacio, tu momento</p><h1>Haz que tu próxima idea encuentre su lugar.</h1><p>Descubre locales listos para crear, vender, reunirte y hacer crecer lo que imaginas.</p><button class="primary-btn" onclick="document.querySelector('#search').focus()">Explorar espacios <span class="material-symbols-outlined" style="vertical-align:middle;font-size:18px">arrow_forward</span></button></div><img class="hero-mark" src="${heroLogo}" alt=""/></div><div class="search-bar" id="search"><div class="search-field"><span>UBICACIÓN</span><strong>${searchState.location}</strong></div><div class="search-field property-name-field"><span>NOMBRE DE LA PROPIEDAD</span><input id="property-name-search" type="search" aria-label="Buscar propiedad por nombre" value="${escapeHTML(searchState.nameQuery||'')}" placeholder="Ej. Kitchen Lab Chapinero"/></div><div class="search-field"><span>TIPO DE ESPACIO</span><strong>Cualquier categoría</strong></div><div class="search-field"><span>PRESUPUESTO</span><strong>Cualquier presupuesto</strong></div><div class="search-field"><span>FECHAS</span><strong>Agregar fechas</strong></div><button class="search-go" onclick="active='filters';render()"><span class="material-symbols-outlined">tune</span></button></div><div class="section-head"><h2>Explora por categoría</h2><button class="link-btn" onclick="toast('Todas las categorías disponibles')">Ver todas</button></div><div class="category-row">${[['restaurant','Gastro'],['shopping_bag','Retail'],['work','Oficinas'],['medical_services','Salud'],['face','Belleza'],['build','Talleres']].map((x,i)=>`<button class="category ${i===0?'active':''}" onclick="this.classList.toggle('active')"><span class="material-symbols-outlined">${x[0]}</span>${x[1]}</button>`).join('')}</div><div class="potential-callout"><div><p class="eyebrow">Una nueva forma de empezar</p><h2>¿Tienes un espacio en casa?</h2><p>Descubre garajes, habitaciones con ventana a la calle y jardines frontales que pueden convertirse en tu próximo local en Bogotá.</p></div><button class="secondary-btn" onclick="active='potential';render()">Ver espacios con potencial <span class="material-symbols-outlined" style="vertical-align:middle;font-size:18px">arrow_forward</span></button></div><div class="section-head"><div><h2>${resultLabel}</h2>${searchState.furnishing==='unfurnished'?'<p class="results-note">Mostrando únicamente espacios libres, listos para adaptar a tu negocio.</p>':''}</div><button class="link-btn" onclick="active='map';render()">Ver todos</button></div><div class="cards">${recommendedSpaces().map(card).join('')}</div></section>`; }
function potential() { return `<section class="view potential-view"><div class="potential-hero"><div><p class="eyebrow">Espacios con potencial de local</p><h1>Convierte un rincón de tu casa en una oportunidad.</h1><p>Explora espacios personales en barrios de Bogotá que pueden recibir una idea comercial por horas, días o semanas.</p></div><span class="material-symbols-outlined potential-hero-icon">home_work</span></div><div class="section-head potential-heading"><div><h2>Oportunidades cerca de ti</h2><p>Inspiradas en las casas y frentes comerciales de Galerías, Teusaquillo y barrios vecinos.</p></div><button class="secondary-btn" onclick="active='discover';render()"><span class="material-symbols-outlined" style="vertical-align:middle;font-size:18px">arrow_back</span> Volver al inicio</button></div><div class="cards potential-cards">${potentialSpaces.map(item=>`<article class="card potential-card"><div class="card-image" style="background-image:url('${item.image}')"><span class="badge orange">${item.badge}</span><button class="heart" onclick="toggleHeart(this)"><span class="material-symbols-outlined">favorite</span></button></div><div class="card-content"><h3>${item.title}</h3><div class="card-location"><span class="material-symbols-outlined">location_on</span>${item.location}</div><p class="potential-description">${item.description}</p><div class="card-meta"><div class="tags">${item.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div><div class="price">${item.price}<small>${item.unit}</small></div></div><button class="potential-action" onclick="toast('Te mostraremos cómo activar este espacio')">Me interesa este espacio</button></div></article>`).join('')}</div></section>`; }
function mapView() { return `<section class="view"><div class="map-panel"><div class="map-top"><span class="material-symbols-outlined">arrow_back</span><input value="Malasaña, Madrid" aria-label="Ubicación"/><button class="icon-btn" onclick="active='filters';render()"><span class="material-symbols-outlined">tune</span></button></div><span class="pin" style="top:33%;left:20%">€45/h</span><span class="pin selected" style="top:50%;left:56%">€180/d</span><span class="pin" style="top:72%;left:31%">€60/h</span><button class="secondary-btn" style="position:absolute;left:24px;bottom:145px" onclick="toast('Cambiando a vista de lista')"><span class="material-symbols-outlined" style="vertical-align:middle">format_list_bulleted</span> Lista</button><button class="icon-btn" style="position:absolute;right:24px;bottom:145px;background:white" onclick="toast('Ubicación actualizada')"><span class="material-symbols-outlined">my_location</span></button><div class="map-list">${listings.slice(0,2).map(x=>`<div class="map-card" onclick="active='booking';render()"><div class="mini-img" style="background-image:url('${x.image}')"></div><div class="card-content"><h3>${x.title}</h3><div class="card-location">${x.tags.join(' · ')} · 45m²</div><div class="price">${x.price}${x.unit}</div></div></div>`).join('')}</div></div></section>`; }
function publish() { return `<section class="view flow-screen publish-view"><button class="back-btn" onclick="active='discover';render()"><span class="material-symbols-outlined">arrow_back</span> Volver al inicio</button><div class="section-head publish-heading"><div><p class="eyebrow">Registro de propietario</p><h1>Publica tu espacio</h1><p>Cuéntanos qué lugar quieres convertir en una oportunidad comercial temporal.</p></div><span class="publish-step">Paso 1 de 3</span></div><div class="publish-layout"><div class="panel publish-panel"><h2>Fotos del espacio</h2><p class="panel-help">Muestra el acceso, la fachada, la luz y el área completa. Puedes subir hasta 6 fotos.</p><label class="photo-upload"><input type="file" accept="image/*" multiple onchange="handlePhotoUpload(this)"><span class="material-symbols-outlined">add_photo_alternate</span><strong>Subir fotos del local</strong><small>JPG o PNG · Arrastra tus imágenes aquí</small></label><div id="photo-preview" class="photo-preview"></div><div class="publish-tip"><span class="material-symbols-outlined">lightbulb</span><span>Una buena foto de la entrada ayuda a que las personas entiendan cómo funciona el espacio.</span></div></div><div class="panel publish-panel"><h2>Datos del local</h2><div class="form-grid"><div class="form-field"><label>NOMBRE DEL ESPACIO</label><input placeholder="Ej. Garaje Galerías"/></div><div class="form-field"><label>TIPO DE ESPACIO</label><select><option>Local comercial</option><option>Garaje</option><option>Habitación con ventana a la calle</option><option>Jardín frontal</option><option>Corredor de edificio</option></select></div><div class="form-field"><label>ÁREA APROXIMADA</label><input type="number" min="1" placeholder="Ej. 18"/></div><div class="form-field"><label>UNIDAD</label><select><option>m²</option><option>m lineales</option></select></div><div class="form-field full-field"><label>DIRECCIÓN O ZONA</label><input placeholder="Ej. Calle 53 con Carrera 24, Galerías, Bogotá"/></div><div class="form-field full-field"><label>ESPECIFICACIONES</label><textarea rows="4" placeholder="Acceso independiente, ventana a la calle, baño, luz natural, altura, restricciones..."></textarea></div></div></div><div class="panel publish-panel publish-questionnaire"><h2>Cuestionario del espacio</h2><p class="panel-help">Estas respuestas ayudan a las personas a saber si el lugar sirve para su idea.</p><div class="question"><strong>¿Qué tipo de actividad puede recibir?</strong><div class="question-options"><label><input type="checkbox"> Gastro</label><label><input type="checkbox"> Retail</label><label><input type="checkbox"> Servicios</label><label><input type="checkbox"> Talleres</label></div></div><div class="question"><strong>¿Cómo es el acceso?</strong><div class="question-options"><label><input type="radio" name="access"> Directo desde la calle</label><label><input type="radio" name="access"> Por zona común</label><label><input type="radio" name="access"> Requiere coordinación</label></div></div><div class="question"><strong>¿Qué disponibilidad ofreces?</strong><div class="question-options"><label><input type="checkbox"> Por hora</label><label><input type="checkbox"> Por día</label><label><input type="checkbox"> Por semana</label></div></div></div></div><div class="publish-actions"><button class="secondary-btn" onclick="active='discover';render()">Guardar y salir</button><button class="primary-btn" onclick="toast('Registro guardado como borrador')">Guardar registro <span class="material-symbols-outlined" style="vertical-align:middle;font-size:18px">arrow_forward</span></button></div></section>`; }
function owner() { return `<section class="view"><div class="dashboard-grid"><div class="metric-card"><p class="eyebrow" style="color:#d9c4ff">Ingresos de este mes</p><div class="metric">€12.450</div><div class="metric-row"><div>Ocupación media<b>92%</b></div><div>Días alquilados<b>28/31</b></div></div></div><div class="chart-card"><div class="section-head" style="margin:0"><h3>Visitas al perfil</h3><span style="color:var(--muted);font-size:13px">Últimos 7 días</span></div><div class="bars">${[35,60,45,78,40,92,65].map((h,i)=>`<div class="bar ${i===5?'active':''}" style="height:${h}%"></div>`).join('')}</div><div class="bar-labels">${['L','M','X','J','V','S','D'].map(x=>`<span>${x}</span>`).join('')}</div></div></div><div class="section-head"><h2>Mis espacios</h2><button class="link-btn">Ver todos</button></div><div class="cards">${listings.slice(1).concat(listings.slice(0,1)).map(card).join('')}</div><div class="section-head"><h2>Próximas reservas</h2><button class="link-btn" onclick="active='inbox';render()">Ver mensajes</button></div><div class="reservations"><div class="reservation"><div class="avatar">CM</div><div class="reservation-info"><strong>Carlos Méndez</strong><p>The Creative Loft · 12 oct - 14 oct</p></div><span class="reservation-date">Mañana</span><span class="material-symbols-outlined">chat_bubble</span></div><div class="reservation"><div class="avatar">ER</div><div class="reservation-info"><strong>Elena Rius</strong><p>Kitchen Lab Industrial · 16 oct - 16 oct</p></div><span class="reservation-date">En 4 días</span><span class="material-symbols-outlined">chat_bubble</span></div></div></section>`; }
