function verify() { return `<section class="view verify"><p class="eyebrow">Paso 1 de 4</p><div class="progress"><span class="done"></span><span></span><span></span><span></span></div><div class="verify-card"><h1>Verifica tu negocio</h1><p style="color:var(--muted);line-height:1.6">Queremos asegurarnos de que tu espacio y tu negocio estén listos para recibir nuevas oportunidades.</p><div class="upload" onclick="toast('Selector de archivos disponible en la siguiente versión')"><div><span class="material-symbols-outlined" style="font-size:40px;color:var(--purple)">upload_file</span><h3>Sube tu documento</h3><p>PDF, JPG o PNG · Máximo 10 MB</p></div></div><div class="form-field"><label>NOMBRE DEL NEGOCIO</label><input placeholder="Ej. The Creative Loft"/></div><div class="verify-actions"><button class="link-btn" onclick="active='discover';render()">Ahora no</button><button class="primary-btn" onclick="toast('Avanzando al siguiente paso')">Continuar <span class="material-symbols-outlined" style="vertical-align:middle;font-size:17px">arrow_forward</span></button></div></div></section>`; }
function favorites() { return `<section class="view"><div class="section-head" style="margin-top:0"><div><p class="eyebrow">Tu colección</p><h1>Favoritos</h1></div><button class="secondary-btn" onclick="toast('Lista compartida')"><span class="material-symbols-outlined" style="vertical-align:middle;font-size:18px">share</span> Compartir</button></div><div class="cards">${listings.slice(0,2).map(card).join('')}</div></section>`; }
function filters() { return `<section class="view flow-screen"><button class="back-btn" onclick="active='discover';render()"><span class="material-symbols-outlined">arrow_back</span> Search Discover</button><div class="section-head" style="margin-top:22px"><div><p class="eyebrow">Personaliza tu búsqueda</p><h1>Filtros</h1></div><button class="link-btn" onclick="toast('Filtros restablecidos')">Restablecer</button></div><div class="filter-grid"><div class="panel"><h3>Tipo de espacio</h3><div class="choice-grid">${['Gastro','Retail','Oficinas','Salud','Belleza','Talleres'].map((x,i)=>`<button class="choice ${i===0?'selected':''}" onclick="this.classList.toggle('selected')"><span class="material-symbols-outlined">${['restaurant','shopping_bag','work','medical_services','face','build'][i]}</span>${x}</button>`).join('')}</div></div><div class="panel"><h3>Presupuesto</h3><div class="range-line"><span>€50</span><b>€2.500+</b></div><input class="range" type="range" min="50" max="2500" value="900"/><h3 style="margin-top:28px">Duración</h3><div class="choice-grid compact"><button class="choice selected"><span class="material-symbols-outlined">schedule</span>Por horas</button><button class="choice"><span class="material-symbols-outlined">calendar_today</span>Por días</button><button class="choice"><span class="material-symbols-outlined">calendar_month</span>Por meses</button></div></div><div class="panel"><h3>Amenidades</h3>${['WiFi de alta velocidad','Aire acondicionado','Mobiliario incluido','Cocina / Office','Escaparate a pie de calle'].map((x,i)=>`<label class="check-row"><input type="checkbox" ${i<2?'checked':''}/> <span>${x}</span><span class="material-symbols-outlined">${i<2?'check':'add'}</span></label>`).join('')}</div></div><button class="primary-btn apply-btn" onclick="active='discover';render();toast('Filtros aplicados')">Mostrar espacios</button></section>`; }
