function chatDetail() { return `<section class="view flow-screen narrow"><button class="back-btn" onclick="active='inbox';render()"><span class="material-symbols-outlined">arrow_back</span> Detalle Chat</button><div class="panel chat-detail"><div class="chat-head"><h2>The Creative Loft</h2><span class="verified">● Activo ahora</span></div><div class="chat-body"><div class="bubble">Hola, tu espacio ya está listo para el montaje de mañana.</div><div class="bubble mine">¡Perfecto! Nos vemos a las 10:00. Gracias.</div><div class="bubble">Nos vemos 👋</div></div><div class="chat-input"><input placeholder="Escribe un mensaje..."/><button class="icon-btn" onclick="toast('Mensaje enviado')"><span class="material-symbols-outlined">send</span></button></div></div></section>`; }
