function verifyDoc() { return `<section class="view flow-screen verify"><button class="back-btn" onclick="active='verifyStart';render()"><span class="material-symbols-outlined">arrow_back</span> Captura de documento</button><div class="verify-card centered"><p class="eyebrow">Paso 1 de 2</p><h1>Captura de documento</h1><div class="camera-frame"><span class="material-symbols-outlined">badge</span><b>FRENTE DEL DOCUMENTO</b><small>Listo para capturar</small></div><p class="tip"><span class="material-symbols-outlined">lightbulb</span> Consejo de experto: asegúrate de tener buena luz y todos los bordes visibles.</p><button class="primary-btn full" onclick="active='verifySelfie';render()">Capturar documento</button></div></section>`; }
function verifySelfie() { return `<section class="view flow-screen verify"><button class="back-btn" onclick="active='verifyDoc';render()"><span class="material-symbols-outlined">arrow_back</span> Reconocimiento facial</button><div class="verify-card centered"><p class="eyebrow">Paso 2 de 2</p><h1>Validación facial</h1><div class="face-frame"><span class="material-symbols-outlined">face_6</span><b>Buscando rostro...</b><small>Buena luz · Sin gafas · Rostro descubierto</small></div><button class="primary-btn full" onclick="active='verifyBusiness';render()">Tomar selfie</button></div></section>`; }
function verifyBusiness() { return `<section class="view flow-screen verify"><button class="back-btn" onclick="active='verifyStart';render()"><span class="material-symbols-outlined">arrow_back</span> Revisión de datos</button><div class="progress"><span class="done"></span><span class="done"></span><span class="done"></span></div><div class="verify-card"><p class="eyebrow">Paso 2 de 3 · 66% completado</p><h1>Sobre tu negocio</h1><p>Cuéntanos qué haces para completar tu perfil de emprendedor.</p><div class="choice-grid">${['Restaurante','Boutique','Oficina','Otro'].map((x,i)=>`<button class="choice ${i===0?'selected':''}"><span class="material-symbols-outlined">${['restaurant','styler','work','more_horiz'][i]}</span>${x}</button>`).join('')}</div><div class="form-field"><label>DESCRIPCIÓN DE LA ACTIVIDAD</label><input placeholder="Describe brevemente tu negocio"/></div><button class="primary-btn full" onclick="active='verifyStatus';render()">Enviar para revisión <span class="material-symbols-outlined" style="vertical-align:middle;font-size:18px">send</span></button></div></section>`; }
