function normalizeCity(value) { const text=String(value||'').toLowerCase(); const found=Object.keys(cityCenters).find(city=>text.includes(city.split(',')[0].toLowerCase())); return found||'Yopal, Colombia'; }
function ensureCitySpaces(city) { const existing=spaces.filter(space=>normalizeCity(space.location||'')===city && Number.isFinite(space.latitude) && Number.isFinite(space.longitude)); if(existing.length>=5) return existing; const center=cityCenters[city]||cityCenters['Yopal, Colombia']; const cityName=city.split(',')[0]; let seed=[...city].reduce((sum,char)=>((sum*31)+char.charCodeAt(0))%997,17); const random=()=>{seed=(seed*9301+49297)%233280; return seed/233280;}; mapSpaceTemplates.slice(existing.length).forEach((template,index)=>{ const id=`LOC-${cityName.slice(0,3).toUpperCase()}-${Date.now().toString(36)}-${index}`; const space={id,title:`${template.name} ${cityName}`,name:`${template.name} ${cityName}`,location:`${cityName}, Colombia`,latitude:center[0]+((random()-.5)*.065),longitude:center[1]+((random()-.5)*.085),mainImage:photos.emptyGallery, image:photos.emptyGallery,price:template.price,unit:`/${template.unit}`,prices:{hour:template.unit==='hora'?template.price:undefined,day:template.unit==='día'?template.price:undefined,week:template.unit==='semana'?template.price:undefined,fortnight:template.unit==='quincena'?template.price:undefined,month:template.unit==='mes'?template.price:undefined},tags:template.detail.split(' · '),detail:template.detail, furnishing:template.detail.includes('Sin')?'Sin amoblar':template.detail.includes('Amoblado')?'Amoblado':'Sin amoblar',availability:'Disponible',rating:4.8,distance:'2.4 km',businessTypes:template.detail.includes('Gastro')?['Restaurante','Cafetería']:template.detail.includes('Retail')?['Boutique','Showroom']:['Oficina','Consultorio'],badge:'Publicado'}; spaces.push(space); }); return spaces.filter(space=>normalizeCity(space.location||'')===city && Number.isFinite(space.latitude) && Number.isFinite(space.longitude)); }
function citySpaces(city) { return ensureCitySpaces(city).map(space=>({ ...space, position:[space.latitude,space.longitude], name:space.name||space.title, detail:space.detail||space.tags?.join(' · '), price:space.price||Object.values(space.prices||{}).find(Boolean)||0, unit:(space.unit||'/día').replace('/',''), selected:space.id===selectedSpaceId })); }
function formatMapPrice(value) { return `$${new Intl.NumberFormat('es-CO').format(value)}`; }
let activeMap=null; let activeMapLayer=null; let mapRefreshTimer=null;
function filteredMapSpaces(city,map) { const bounds=map.getBounds(); return ensureCitySpaces(city).filter(space=>Number.isFinite(space.latitude)&&Number.isFinite(space.longitude)&&bounds.contains([space.latitude,space.longitude])).filter(space=>mapState.business==='all'||(space.businessTypes||[]).includes(mapState.business)).filter(space=>mapState.furnishing==='all'||space.furnishing===mapState.furnishing).filter(space=>mapState.availability==='all'||space.availability===mapState.availability).filter(space=>{const amount=Number(space.price)||0; return mapState.price==='all'||(mapState.price==='low'&&amount<=100000)||(mapState.price==='mid'&&amount>100000&&amount<=300000)||(mapState.price==='high'&&amount>300000&&amount<=700000)||(mapState.price==='premium'&&amount>700000);}); }
