function addMapEnhancements() { const panel=document.querySelector('.map-panel'); if(!panel||panel.querySelector('.map-filter-bar')) return; panel.querySelector('.map-top')?.insertAdjacentHTML('afterend',`<div class="map-filter-bar"><select data-map-filter="price"><option value="all">Precio</option><option value="low">Hasta $100.000</option><option value="high">Más de $100.000</option></select><select data-map-filter="business"><option value="all">Tipo de negocio</option>${['Restaurante','Cafetería','Barbería','Salón de belleza','Boutique','Oficina','Consultorio','Showroom','Food truck','Papelería','Tecnología','Otros'].map(item=>`<option>${item}</option>`).join('')}</select><select data-map-filter="furnishing"><option value="all">Tipo de espacio</option><option>Amoblado</option><option>Semi amoblado</option><option>Sin amoblar</option></select><select data-map-filter="availability"><option value="all">Disponibilidad</option><option value="Disponible hoy">Disponible hoy</option><option value="Disponible">Disponible</option></select><button class="map-near-btn" onclick="locateMapUser()"><span class="material-symbols-outlined">my_location</span>Cerca de mí</button><button class="map-more-btn" onclick="active='filters';render()">Más filtros</button></div><div class="map-results-count">0 espacios visibles</div>`); panel.querySelector('.map-list')?.insertAdjacentHTML('beforebegin','<div class="map-selected-card"></div>'); panel.querySelectorAll('[data-map-filter]').forEach(select=>{select.value=mapState[select.dataset.mapFilter]; select.onchange=()=>{mapState[select.dataset.mapFilter]=select.value; if(activeMap) renderMapMarkers(activeMap,normalizeCity(searchState.location));};}); }
