propertyDetail = function() { const space=spaces.find(item=>item.id===selectedSpaceId)||spaces[0]; let html=basePropertyDetail(); const description=escapeHTML(space.description||'Espacio comercial listo para recibir tu próxima idea.'); const publishedInfo=`<div class="property-section published-space-data"><h2>Datos publicados por el propietario</h2><div class="conditions-meta"><div><span class="material-symbols-outlined">straighten</span><span><strong>Tipo y tamaño</strong><small>${escapeHTML(space.spaceType||'Espacio comercial')}${space.area?` · ${escapeHTML(space.area)} ${escapeHTML(space.areaUnit||'m²')}`:''}</small></span></div><div><span class="material-symbols-outlined">event_available</span><span><strong>Disponibilidad</strong><small>${escapeHTML((space.availabilityOptions||[]).join(' · ')||'Consultar con el propietario')}</small></span></div><div><span class="material-symbols-outlined">category</span><span><strong>Actividades</strong><small>${escapeHTML((space.activities||[]).join(' · ')||'Actividad flexible')}</small></span></div><div><span class="material-symbols-outlined">door_front</span><span><strong>Acceso</strong><small>${escapeHTML(space.access||'Información confirmada por el propietario')}</small></span></div></div></div>`; const reserved=space.availability==='Reservado'&&space.reservedUntil; const until=space.reservedUntil?new Intl.DateTimeFormat('es-CO',{dateStyle:'long'}).format(new Date(`${space.reservedUntil}T12:00:00`)):''; const followLabel=followedSpaceIds().includes(space.id)?'Dejar de seguir':'Seguir disponibilidad'; const availabilityPanel=`<div class="space-availability-panel ${reserved?'is-reserved':''}"><strong>${reserved?'Reservado hasta '+escapeHTML(until):'Disponible para reservar'}</strong>${reserved?'<small>Haz seguimiento y envía una oferta para cuando quede libre.</small>':''}<div class="availability-actions"><button class="secondary-btn" onclick="followSpace('${space.id}')"><span class="material-symbols-outlined">notifications</span>${followLabel}</button>${reserved?`<button class="primary-btn" onclick="openOfferModal('${space.id}')">Hacer una oferta</button>`:''}</div></div>`; html=html.replace('Un espacio comercial listo para recibir tu próxima idea. Ideal para emprendedores que buscan una ubicación estratégica, flexible y preparada para comenzar a operar.',description); html=html.replace('El propietario comparte el lugar para que puedas crear, vender, atender clientes o hacer crecer tu negocio por horas, días o semanas.',`${escapeHTML(space.spaceType||'Espacio comercial')} · ${space.area?`${escapeHTML(space.area)} ${escapeHTML(space.areaUnit||'m²')} · `:''}${space.access?escapeHTML(space.access):'Condiciones definidas por el propietario.'}`); html=html.replace('<div class="property-section"><h2>Lo que este lugar ofrece</h2>',`${publishedInfo}<div class="property-section"><h2>Lo que este lugar ofrece</h2>`); html=html.replace('<div class="booking-price">',`${availabilityPanel}<div class="booking-price">`); return html.replace('</main>',`${propertyConditions(space)}</main>`); };
