function reservationDone() { const space=reservationSpace(); const total=reservationTotal(); return `<section class="view flow-screen confirmation reservation-confirmation"><div class="success-icon"><span class="material-symbols-outlined">check_circle</span></div><p class="eyebrow">Solicitud enviada</p><h1>¡Tu reserva está en camino!</h1><p>El propietario recibirá tu solicitud y te enviaremos una confirmación a <b>${reservationState.guestEmail||'tu correo'}</b>.</p><div class="panel"><div class="detail-row"><span>Espacio</span><b>${space.name||space.title}</b></div><div class="detail-row"><span>Unidad reservada</span><b>${reservationState.quantity} · Por ${{hour:'hora',day:'día',week:'semana',fortnight:'quincena',month:'mes'}[reservationState.unit]}</b></div><div class="detail-row"><span>Total estimado</span><b>${formatMapPrice(total.total)}</b></div><div class="detail-row"><span>Código de solicitud</span><b>LOC-${String(Date.now()).slice(-6)}</b></div></div><button class="primary-btn full" onclick="active='discover';render()">Volver a explorar</button></section>`; }
