const baseInitRealMap = initRealMap;
initRealMap = function() {
  baseInitRealMap();
  const input = document.querySelector('#map-location-search');
  if (!input) return;
  input.onkeydown = event => {
    if (event.key === 'Enter') {
      event.preventDefault();
      searchForLocation(input.value);
    }
  };
  input.oninput = () => {
    clearTimeout(locationAutocompleteTimer);
    locationAutocompleteTimer = setTimeout(() => loadLocationSuggestions(input), 300);
  };
  input.onfocus = () => loadLocationSuggestions(input);
  if (activeMap && locationState.latitude && locationState.longitude) {
    activeMap.setView([locationState.latitude, locationState.longitude], 15, {animate:false});
  }
};

locateMapUser = async function() {
  if (!navigator.geolocation) {
    toast('Este navegador no permite geolocalización');
    return;
  }
  toast('Obteniendo tu ubicación…');
  locationState.status = 'loading';
  try {
    const position = await new Promise((resolve, reject) => navigator.geolocation.getCurrentPosition(resolve, reject, {enableHighAccuracy:true, timeout:10000, maximumAge:300000}));
    const {latitude, longitude} = position.coords;
    let place;
    try { place = await reverseGeocode(latitude, longitude); } catch (error) { place = {}; }
    const fallback = nearestKnownCity(latitude, longitude);
    applyDetectedLocation(latitude, longitude, place.city || fallback?.city?.split(',')[0], place.country || fallback?.city?.split(',')[1]?.trim());
  } catch (error) {
    locationState.status = 'denied';
    toast('Activa la ubicación del navegador para buscar cerca de ti');
  }
};



