function collectPublishedConditions() {
  const interventionRows=[...document.querySelectorAll('.intervention-row')].map(row=>({label:row.querySelector('span')?.textContent.trim()||'',value:row.querySelector('select')?.value||''})).filter(item=>item.label);
  const grouped={allowed:[],approval:[],blocked:[]};
  interventionRows.forEach(item=>{ if(item.value.startsWith('Sí')||item.value==='Permitido') grouped.allowed.push(item.label); else if(item.value.startsWith('Solo')) grouped.approval.push(item.label); else if(item.value.startsWith('No')) grouped.blocked.push(item.label); });
  const special=[...document.querySelectorAll('.special-fields input,.special-fields textarea')].map(field=>field.value.trim()).filter(Boolean);
  const modificationRows=[...document.querySelectorAll('.modification-row')].map(row=>({label:row.querySelector('span')?.textContent.trim()||'',value:row.querySelector('select')?.value||''})).filter(item=>item.label);
  return {interventionRows,modificationRows,allowed:grouped.allowed,approval:grouped.approval,blocked:grouped.blocked,special,consent:Boolean(document.querySelector('.summary-consent input')?.checked)};
}
