  const space={id:`LOC-${now}`,title:name,name,location:address,latitude:Number(coordinates.latitude),longitude:Number(coordinates.longitude),mainImage:mainPhoto,image:mainPhoto,gallery:photoUrls,price,unit:`/${priceLabels[priceUnit]}`,prices:{[priceUnit]:price},tags,badge:'Publicado',furnishing,availability:'Disponible',rating:null,distance:'Cerca de ti',businessTypes,description:publishField('publish-specs')||'Espacio comercial publicado por su propietario.',spaceType:type,area,areaUnit,activities,access,availabilityOptions:availability,conditions,ownerProfileId:profile.id,ownerName:profile.name,ownerEmail:profile.email,ownerPhone:profile.phone,ownerAccountType:profile.accountType,ownerId:ownerUser.id,createdAt:new Date(now).toISOString()};
  const existingProfileIndex=ownerProfiles.findIndex(item=>item.id===profile.id);
