function applyDateFilter() { const start=document.querySelector('#search-date-start')?.value; const end=document.querySelector('#search-date-end')?.value||start; if(!start) { toast('Selecciona una fecha de inicio'); return; } if(end<start) { toast('La fecha final no puede ser anterior a la inicial'); return; } reservationState.start=start; reservationState.end=end; const formatDate=value=>new Intl.DateTimeFormat('es-CO',{day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date(`${value}T12:00:00`)); searchState.dates=start===end?formatDate(start):`${formatDate(start)} – ${formatDate(end)}`; document.querySelector('.modal-backdrop')?.remove(); render(); toast(`Fechas aplicadas: ${searchState.dates}`); }
const baseOpenSearchPicker=openSearchPicker;
openSearchPicker = function(kind) { if(kind!=='dates') return baseOpenSearchPicker(kind); const today=new Date().toISOString().slice(0,10); const start=reservationState.start||today; const end=reservationState.end||start; document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)this.remove()"><div class="modal search-picker date-picker-modal"><button class="icon-btn modal-close" onclick="this.closest('.modal-backdrop').remove()"><span class="material-symbols-outlined">close</span></button><p class="eyebrow">Disponibilidad</p><h2>¿Cuándo necesitas el espacio?</h2><p class="panel-help">Elige las fechas y las llevaremos automáticamente a tu reserva.</p><div class="form-field"><label>FECHA DE INICIO</label><input id="search-date-start" type="date" min="${today}" value="${start}"></div><div class="form-field"><label>FECHA DE FINALIZACIÓN</label><input id="search-date-end" type="date" min="${today}" value="${end}"></div><button class="primary-btn full" onclick="applyDateFilter()">Aplicar fechas</button><button class="link-btn full" onclick="searchState.dates='Agregar fechas';reservationState.start='';reservationState.end='';this.closest('.modal-backdrop').remove();render()">Limpiar fechas</button></div></div>`; };
function categoryMatches(space,category) { if(!category||category==='Cualquier categoría') return true; const text=[...(space.tags||[]),...(space.businessTypes||[]),space.detail||''].join(' ').toLowerCase(); const terms={Gastro:['gastro','restaurante','cafeter','cocina','bar','café'],Retail:['retail','boutique','showroom','tienda','florister'],Oficinas:['oficina','consultorio','estudio'],Salud:['salud','consultorio','dental','gimnasio'],Belleza:['belleza','salón','beauty'],Talleres:['taller','gimnasio','cerámica']}[category]||[category.toLowerCase()]; return terms.some(term=>text.includes(term)); }
function propertyNameMatches(space,query) { const term=String(query||'').trim().toLocaleLowerCase('es'); if(!term) return true; return [space.name,space.title,...(space.aliases||[])].filter(Boolean).join(' ').toLocaleLowerCase('es').includes(term); }
const baseRecommendedWithCategory= recommendedSpaces;
recommendedSpaces = function() { const source=searchState.nameQuery?spaces.filter(space=>propertyNameMatches(space,searchState.nameQuery)):baseRecommendedWithCategory(); return source.filter(space=>categoryMatches(space,searchState.type)).filter(space=>propertyNameMatches(space,searchState.nameQuery)); };
function activateCategoryFilters() { if(active==='discover') { const buttons=document.querySelectorAll('.category-row .category'); buttons.forEach(button=>{ const label=button.textContent.trim(); button.classList.toggle('active',searchState.type===label); button.onclick=()=>{ searchState.type=searchState.type===label?'Cualquier categoría':label; render(); toast(searchState.type==='Cualquier categoría'?'Mostrando todas las categorías':`Filtro activo: ${searchState.type}`); }; }); } if(active==='filters') { document.querySelectorAll('.filter-grid .choice').forEach(button=>{ const label=button.textContent.trim(); if(['Gastro','Retail','Oficinas','Salud','Belleza','Talleres'].includes(label)) { button.classList.toggle('selected',searchState.type===label); button.onclick=()=>{searchState.type=searchState.type===label?'Cualquier categoría':label; render();}; } }); } }
function submitSearchBox() { const input=document.querySelector('#location-search'); const value=input?.value.trim()||searchState.location; if(value&&value!==searchState.location) { searchForLocation(value); return; } render(); toast(`Buscando ${searchState.type==='Cualquier categoría'?'espacios':searchState.type.toLowerCase()}`); }
function submitPropertyNameSearch() { const input=document.querySelector('#property-name-search'); searchState.nameQuery=input?.value.trim()||''; render(); toast(searchState.nameQuery?`Buscando “${searchState.nameQuery}”`:'Mostrando todas las propiedades'); }
function submitMapSearchBox() { const input=document.querySelector('#map-location-search'); const value=input?.value.trim()||searchState.location; if(value) searchForLocation(value); }
function focusUserLogin(email) { const input=document.querySelector('#login-email'); const password=document.querySelector('#login-password'); if(input) input.value=email; document.querySelector('.account-login-card')?.scrollIntoView({behavior:'smooth',block:'center'}); password?.focus(); }
function activateAccountControls() { if(active!=='profile') return; document.querySelectorAll('.account-user-row').forEach(row=>{ if(row.querySelector('.account-login-button')) return; const email=row.querySelector('small')?.textContent.split(' · ').pop(); if(!email) return; const button=document.createElement('button'); button.className='secondary-btn account-login-button'; button.type='button'; button.textContent='Iniciar sesión'; button.onclick=()=>focusUserLogin(email); row.appendChild(button); }); }
