  const ownReservations=reservations.filter(item=>item.userId===sessionUser.id);
  const reservationsMarkup=ownReservations.length?ownReservations.map(item=>`<div class="reservation"><div class="avatar">${escapeHTML(initialsFor(sessionUser.name))}</div><div class="reservation-info"><strong>${escapeHTML(item.spaceName)}</strong><p>${item.quantity} unidad(es) · ${escapeHTML(item.status)}</p></div><span class="reservation-date">${escapeHTML(item.id)}</span></div>`).join(''):'<div class="panel owner-empty"><p>Aún no tienes reservas guardadas.</p><button class="primary-btn" onclick="active=\'discover\';render()">Explorar espacios</button></div>';
  const privateContent=sessionUser.role==='owner'?'<div class="panel"><p>Administra tus espacios desde el panel del propietario.</p><button class="primary-btn" onclick="active=\'owner\';render()">Abrir panel del propietario</button></div>':`<div class="reservations">${reservationsMarkup}</div>`;
  return `<section class="view flow-screen account-view"><div class="profile-hero"><div class="avatar profile-avatar">${escapeHTML(initialsFor(sessionUser.name))}</div><span class="verified"><span class="material-symbols-outlined">verified_user</span> Sesión activa</span><h1>${escapeHTML(sessionUser.name)}</h1><p>${sessionUser.role==='owner'?'Propietario':'Emprendedor'} · ${escapeHTML(sessionUser.email)}</p></div><div class="account-session"><span class="material-symbols-outlined">verified_user</span><div><strong>Cuenta conectada</strong><p>Los datos privados solo son visibles mientras esta sesión esté activa.</p></div><button class="secondary-btn" onclick="logoutUser()">Cerrar sesión</button></div><div class="section-head"><h2>${sessionUser.role==='owner'?'Mis espacios':'Mis reservas'}</h2></div>${privateContent}</section>`;
