async function updatePilotReservationStatus(id,status) { const local=reservations.find(item=>item.id===id); if(local) { local.status=status==='accepted'?'Solicitud aceptada':'Solicitud rechazada'; saveUsers(); } if(supabaseClient&&sessionUser?.authUser) { const {error}=await supabaseClient.from('reservations').update({status}).eq('id',id).eq('owner_id',sessionUser.id); if(error) { toast(error.message||'No se pudo actualizar la solicitud'); return; } await loadRetentionData(); } render(); toast(status==='accepted'?'Solicitud aceptada':'Solicitud rechazada'); }
const basePilotOwnerDashboard = owner;
owner = function() { const html=basePilotOwnerDashboard(); if(!sessionUser||sessionUser.role!=='owner') return html; const requests=pilotOwnerReservations(); const markup=requests.length?requests.map(item=>{ const space=spaces.find(candidate=>candidate.id===(item.space_id||item.spaceId)); const status=item.status||'requested'; const displayStatus={requested:'Pendiente','Solicitud enviada':'Pendiente',accepted:'Aceptada',rejected:'Rechazada'}[status]||status; return `<article class="pilot-request-row"><div><strong>${escapeHTML(space?.name||item.spaceName||item.space_id||item.spaceId)}</strong><p>${item.quantity||1} unidad(es) · ${escapeHTML(item.start_date||item.startDate||'Fecha abierta')} → ${escapeHTML(item.end_date||item.endDate||'abierta')} · Emprendedor: ${escapeHTML(item.user_id||item.userId||'Usuario')}</p></div><span class="offer-status">${escapeHTML(displayStatus)}</span>${['requested','Solicitud enviada'].includes(status)?`<button class="secondary-btn" onclick="updatePilotReservationStatus('${item.id}','accepted')">Aceptar</button><button class="link-btn" onclick="updatePilotReservationStatus('${item.id}','rejected')">Rechazar</button>`:''}</article>`; }).join(''):'<p class="panel-help">Aún no tienes solicitudes de reserva. Comparte tus espacios de Yopal para recibir las primeras.</p>'; return html.replace('</section>',`<section class="panel pilot-requests"><div class="section-head"><div><p class="eyebrow">Piloto Yopal</p><h2>Solicitudes de reserva</h2><p class="panel-help">Revisa y responde las solicitudes de emprendedores.</p></div><span class="verified">${requests.filter(item=>['requested','Solicitud enviada'].includes(item.status)).length} pendientes</span></div>${markup}</section></section>`); };
const availabilityState={spaceId:null,month:new Date().getMonth(),year:new Date().getFullYear(),selectedDate:''};
function availabilityDateKey(year,month,day) { return `${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`; }
function availabilityCalendarFor(space) { return space.availabilityCalendar&&typeof space.availabilityCalendar==='object'?space.availabilityCalendar:{}; }
function availabilityMonthLabel(year,month) { return new Intl.DateTimeFormat('es-CO',{month:'long',year:'numeric'}).format(new Date(year,month,1)); }
function availabilityCalendarMarkup(space) { const calendar=availabilityCalendarFor(space); const first=new Date(availabilityState.year,availabilityState.month,1).getDay(); const offset=(first+6)%7; const days=new Date(availabilityState.year,availabilityState.month+1,0).getDate(); const cells=[]; for(let i=0;i<offset;i++) cells.push('<span class="availability-day empty"></span>'); for(let day=1;day<=days;day++){ const key=availabilityDateKey(availabilityState.year,availabilityState.month,day); const entry=calendar[key]||{}; const selected=availabilityState.selectedDate===key; const closed=entry.status==='closed'; const price=entry.price?`<small>$${new Intl.NumberFormat('es-CO').format(entry.price)}</small>`:''; cells.push(`<button class="availability-day ${closed?'closed':''} ${selected?'selected':''}" onclick="selectAvailabilityDate('${key}')"><b>${day}</b>${closed?'<span>Cerrado</span>':price||'<span>Abierto</span>'}</button>`); } const selected=availabilityState.selectedDate?calendar[availabilityState.selectedDate]||{}:{}; return `<div class="availability-calendar-modal"><div class="availability-calendar-head"><div><p class="eyebrow">Disponibilidad del espacio</p><h2>${escapeHTML(space.name||space.title)}</h2><p class="panel-help">Cierra fechas, vuelve a abrirlas o define una tarifa especial para Yopal.</p></div><button class="icon-btn modal-close" onclick="this.closest('.modal-backdrop').remove()"><span class="material-symbols-outlined">close</span></button></div><div class="availability-month-nav"><button class="secondary-btn" onclick="shiftAvailabilityMonth(-1)">←</button><strong>${availabilityMonthLabel(availabilityState.year,availabilityState.month)}</strong><button class="secondary-btn" onclick="shiftAvailabilityMonth(1)">→</button></div><div class="availability-weekdays">${['L','M','X','J','V','S','D'].map(day=>`<span>${day}</span>`).join('')}</div><div class="availability-calendar-grid">${cells.join('')}</div>${availabilityState.selectedDate?`<div class="availability-editor"><strong>${new Intl.DateTimeFormat('es-CO',{dateStyle:'full'}).format(new Date(`${availabilityState.selectedDate}T12:00:00`))}</strong><div class="availability-editor-fields"><label><span>ESTADO</span><select id="availability-status"><option value="open" ${!selected.status||selected.status==='open'?'selected':''}>Disponible</option><option value="closed" ${selected.status==='closed'?'selected':''}>Cerrado</option></select></label><label><span>PRECIO ESPECIAL</span><input id="availability-price" type="number" min="0" value="${selected.price||space.price||0}"></label></div><button class="primary-btn full" onclick="saveAvailabilityDate()">Guardar fecha</button></div>`:'<p class="panel-help availability-hint">Selecciona un día para editar su disponibilidad y precio.</p>'}</div>`; }
function openAvailabilityCalendar(spaceId) { const space=spaces.find(item=>item.id===spaceId); if(!space) return; availabilityState.spaceId=spaceId; availabilityState.month=new Date().getMonth(); availabilityState.year=new Date().getFullYear(); availabilityState.selectedDate=''; document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)this.remove()"><div class="modal availability-modal">${availabilityCalendarMarkup(space)}</div></div>`; }
function selectAvailabilityDate(key) { availabilityState.selectedDate=key; const space=spaces.find(item=>item.id===availabilityState.spaceId); if(space) document.querySelector('.availability-calendar-modal').innerHTML=availabilityCalendarMarkup(space); }
function shiftAvailabilityMonth(delta) { availabilityState.month+=delta; if(availabilityState.month<0){availabilityState.month=11;availabilityState.year--;} if(availabilityState.month>11){availabilityState.month=0;availabilityState.year++;} availabilityState.selectedDate=''; const space=spaces.find(item=>item.id===availabilityState.spaceId); if(space) document.querySelector('.availability-calendar-modal').innerHTML=availabilityCalendarMarkup(space); }
async function persistAvailabilityCalendar(space) { if(!supabaseClient||!sessionUser?.authUser) return; const metadata={gallery:space.gallery||[],tags:space.tags||[],badge:space.badge||'Publicado',businessTypes:space.businessTypes||['Otros'],spaceType:space.spaceType||'',area:space.area||'',areaUnit:space.areaUnit||'m²',activities:space.activities||[],access:space.access||'',availabilityOptions:space.availabilityOptions||[],conditions:space.conditions||{},availabilityCalendar:availabilityCalendarFor(space),ownerName:space.ownerName||sessionUser.name||'',ownerEmail:space.ownerEmail||sessionUser.email||'',ownerPhone:space.ownerPhone||sessionUser.phone||'',ownerAccountType:space.ownerAccountType||sessionUser.accountType||'Propietario'}; const {error}=await supabaseClient.from('spaces').update({metadata}).eq('id',space.id).eq('owner_id',sessionUser.id); if(error) throw error; }
async function saveAvailabilityDate() { const space=spaces.find(item=>item.id===availabilityState.spaceId); const date=availabilityState.selectedDate; if(!space||!date) return; const status=document.querySelector('#availability-status')?.value||'open'; const price=Number(document.querySelector('#availability-price')?.value)||Number(space.price)||0; if(!space.availabilityCalendar) space.availabilityCalendar={}; space.availabilityCalendar[date]=status==='closed'?{status:'closed'}:{status:'open',price}; saveOwnerData(); try { await persistAvailabilityCalendar(space); toast(status==='closed'?'Fecha cerrada':'Fecha disponible y precio guardado'); } catch(error) { toast(error.message||'Guardado local; no se pudo sincronizar Supabase'); } const modal=document.querySelector('.modal-backdrop'); if(modal) { availabilityState.selectedDate=''; modal.querySelector('.availability-calendar-modal').innerHTML=availabilityCalendarMarkup(space); } }
