loginUserFromProfile = async function() { const email=document.querySelector('#login-email')?.value.trim().toLowerCase(); const password=document.querySelector('#login-password')?.value; if(!email||!password) { toast('Escribe correo y contraseña'); return; } try { if(supabaseClient) { const {data,error}=await supabaseClient.auth.signInWithPassword({email,password}); if(!error&&data.user) { await upsertSupabaseProfile(data.user); toast('Sesión iniciada'); render(); return; } if(error&&!isNetworkFetchError(error)) throw error; } const user=users.find(item=>item.email===email&&item.password===password); if(!user) throw new Error('No encontramos esa cuenta local. Si Supabase está desconectado, créala primero en modo local.'); sessionUser=user; saveUsers(); toast('Sesión iniciada en modo local'); render(); } catch(error) { toast(error.message||'No se pudo iniciar sesión'); } };
const baseLoadSupabaseSessionWithFallback=loadSupabaseSession;
