let passwordResetEmail='';
function passwordReset() { if(sessionUser?.authUser) return passwordResetConfirm(); return `<section class="view flow-screen narrow account-view"><button class="back-btn" onclick="active='profile';render()"><span class="material-symbols-outlined">arrow_back</span> Volver a iniciar sesión</button><div class="panel password-reset-card"><div class="password-reset-icon"><span class="material-symbols-outlined">lock_reset</span></div><p class="eyebrow">Recuperar acceso</p><h1>¿Olvidaste tu contraseña?</h1><p class="panel-help">Te enviaremos un enlace para restablecerla. En el piloto local también puedes continuar desde este dispositivo.</p><div class="form-field"><label>CORREO ELECTRÓNICO</label><input id="reset-email" type="email" value="${escapeHTML(passwordResetEmail)}" placeholder="tu@email.com"></div><button class="primary-btn full" onclick="requestPasswordReset()">Enviar instrucciones <span class="material-symbols-outlined">arrow_forward</span></button><button class="link-btn full" onclick="active='profile';render()">Volver al inicio de sesión</button></div></section>`; }
function passwordResetConfirm() { return `<section class="view flow-screen narrow account-view"><div class="panel password-reset-card"><div class="password-reset-icon"><span class="material-symbols-outlined">key</span></div><p class="eyebrow">Nueva contraseña</p><h1>Restablece tu acceso</h1><p class="panel-help">Usa una contraseña de mínimo 6 caracteres para continuar.</p><div class="form-field"><label>NUEVA CONTRASEÑA</label><input id="new-password" type="password" minlength="6" placeholder="Mínimo 6 caracteres"></div><div class="form-field"><label>CONFIRMA LA CONTRASEÑA</label><input id="new-password-confirm" type="password" minlength="6" placeholder="Repite tu contraseña"></div><button class="primary-btn full" onclick="saveNewPassword()">Guardar nueva contraseña</button></div></section>`; }
async function requestPasswordReset() { const email=document.querySelector('#reset-email')?.value.trim().toLowerCase(); if(!email){toast('Escribe tu correo electrónico');return;} passwordResetEmail=email; try { if(supabaseClient) { const {error}=await supabaseClient.auth.resetPasswordForEmail(email,{redirectTo:`${location.origin}${location.pathname}?screen=passwordReset`}); if(error&&!isNetworkFetchError(error)) throw error; if(!error){toast('Revisa tu correo para continuar');return;} } const user=users.find(item=>item.email===email); if(!user) throw new Error('No encontramos una cuenta con ese correo'); active='passwordResetConfirm'; render(); toast('Puedes crear una nueva contraseña en este dispositivo'); } catch(error) { if(isNetworkFetchError(error)) { const user=users.find(item=>item.email===email); if(user){active='passwordResetConfirm';render();toast('Modo local: crea una nueva contraseña');return;} } toast(error.message||'No se pudo iniciar la recuperación'); } }
async function saveNewPassword() { const password=document.querySelector('#new-password')?.value; const confirmation=document.querySelector('#new-password-confirm')?.value; if(!password||password.length<6){toast('La contraseña debe tener mínimo 6 caracteres');return;} if(password!==confirmation){toast('Las contraseñas no coinciden');return;} try { if(sessionUser?.authUser&&supabaseClient) { const {error}=await supabaseClient.auth.updateUser({password}); if(error) throw error; toast('Contraseña actualizada correctamente'); active='profile'; render(); return; } const user=users.find(item=>item.email===passwordResetEmail); if(!user) throw new Error('No encontramos la cuenta local'); user.password=password; sessionUser=user; saveUsers(); active='profile'; render(); toast('Contraseña actualizada en este dispositivo'); } catch(error) { toast(error.message||'No se pudo actualizar la contraseña'); } }
const baseProfileWithPasswordReset=profile;
