requestPasswordReset = async function() { const email=document.querySelector('#reset-email')?.value.trim().toLowerCase(); if(!email){toast('Escribe tu correo electrónico');return;} passwordResetEmail=email; if(!supabaseClient){toast('El restablecimiento por correo requiere conectar Supabase');return;} try { const {error}=await supabaseClient.auth.resetPasswordForEmail(email,{redirectTo:`${location.origin}${location.pathname}?screen=passwordReset`}); if(error) throw error; toast('Revisa tu correo de Localmente para restablecer la contraseña'); } catch(error) { toast(isNetworkFetchError(error)?'No se pudo contactar el servicio de correo. Revisa la configuración de Supabase.':(error.message||'No se pudo enviar el correo')); } };
saveNewPassword = async function() { const password=document.querySelector('#new-password')?.value; const confirmation=document.querySelector('#new-password-confirm')?.value; if(!password||password.length<6){toast('La contraseña debe tener mínimo 6 caracteres');return;} if(password!==confirmation){toast('Las contraseñas no coinciden');return;} if(!supabaseClient){toast('El restablecimiento por correo requiere conectar Supabase');return;} try { const {error}=await supabaseClient.auth.updateUser({password}); if(error) throw error; toast('Contraseña actualizada correctamente'); active='profile'; render(); } catch(error) { toast(error.message||'No se pudo actualizar la contraseña'); } };
